values ('bbbb0001-0000-4000-8000-00000000000d', 'en', null, 'Calculus II', 'The integral half of the calculus story — techniques for evaluating integrals, the geometric and physical quantities they measure, improper integrals, and the infinite sums that become sequences, series, and Taylor expansions. Structure adapted from OpenStax Calculus Volume 2 (CC BY-NC-SA 4.0).', null, 'foundations', 13, true, 'math', '{bbbb0001-0000-4000-8000-000000000007}')
